import{_ as o,o as a,c as n,a6 as t}from"./chunks/framework.ZMCvXf1_.js";const g=JSON.parse('{"title":"CLI flag conventions","description":"","frontmatter":{},"headers":[],"relativePath":"cli/flags.md","filePath":"cli/flags.md"}'),c={name:"cli/flags.md"};function d(r,e,s,l,i,m){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="cli-flag-conventions" tabindex="-1">CLI flag conventions <a class="header-anchor" href="#cli-flag-conventions" aria-label="Permalink to “CLI flag conventions”">​</a></h1><p><code>noorm</code>&#39;s CLI is built on <a href="https://github.com/unjs/citty" target="_blank" rel="noreferrer">citty</a>, which parses flags relative to the subcommand they belong to — a flag typed before the subcommand name never reaches the leaf command&#39;s own parser. <code>noorm</code> works around that for the one flag that genuinely needs to run before dispatch, by stripping it out of <code>argv</code> before citty ever sees it. This page covers that flag and the rule for everything else.</p><h2 id="global-flags-vs-per-subcommand-flags" tabindex="-1">Global flags vs per-subcommand flags <a class="header-anchor" href="#global-flags-vs-per-subcommand-flags" aria-label="Permalink to “Global flags vs per-subcommand flags”">​</a></h2><p>A flag is <strong>global</strong> when <code>noorm</code> recognizes and hoists it regardless of where it appears — before or after the subcommand. A flag is <strong>per-subcommand</strong> when it&#39;s owned by an individual command like <code>noorm sql query</code> and only works <em>after</em> the subcommand name.</p><p><code>noorm</code> hoists exactly one flag on purpose — most flags vary in meaning per command (<code>-c</code> is <code>--cwd</code> at the root, but <code>--config</code> on many subcommands), so per-subcommand parsing is the default for everything else, <code>--dry-run</code>/<code>--json</code>/<code>--yes</code> included.</p><h3 id="the-one-global-c-cwd-path" tabindex="-1">The one global: <code>-c</code> / <code>--cwd &lt;path&gt;</code> <a class="header-anchor" href="#the-one-global-c-cwd-path" aria-label="Permalink to “The one global: -c / --cwd &lt;path&gt;”">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Purpose</th></tr></thead><tbody><tr><td><code>--cwd &lt;path&gt;</code> / <code>-c &lt;path&gt;</code></td><td>Change working directory before resolving <code>.noorm/</code>. Same idea as <code>git -C</code>. Recognized only <strong>before</strong> the subcommand — see the note below.</td></tr></tbody></table><p><code>--cwd</code>/<code>-c</code> is global for two reasons:</p><ol><li>It&#39;s consumed <strong>before dispatch</strong> — it sets the working directory everything else (project discovery, config resolution) resolves against, so it&#39;s genuinely the CLI&#39;s own flag rather than any subcommand&#39;s.</li><li><code>-c</code> already means <code>--config</code> <em>after</em> the subcommand (see the overload note below). Hoisting it lets <code>noorm -c &lt;path&gt; run build</code> mean cwd while <code>noorm run build -c &lt;name&gt;</code> means config, without either shadowing the other.</li></ol><p>Examples:</p><pre><code>noorm -c packages/db run build
noorm --cwd /repos/myapp change ff
</code></pre><p><code>--help</code>/<code>-h</code> and <code>--version</code>/<code>-v</code> are also recognized outside this mechanism — that&#39;s citty&#39;s own framework behaviour, not a <code>noorm</code>-specific hoist.</p><p>An unrecognized flag placed before the subcommand is an error, not a silent no-op:</p><pre><code>$ noorm --bogus-flag config list
Error: Unrecognized flag &#39;--bogus-flag&#39; before the subcommand — noorm can&#39;t forward it there.
The only root-level flag is -c/--cwd &lt;path&gt;; every other flag goes on the command that uses it.
Move &#39;--bogus-flag&#39; after the subcommand instead, e.g. noorm &lt;command&gt; ... --bogus-flag.
</code></pre><h3 id="per-subcommand-flags-after-the-subcommand" tabindex="-1">Per-subcommand flags (after the subcommand) <a class="header-anchor" href="#per-subcommand-flags-after-the-subcommand" aria-label="Permalink to “Per-subcommand flags (after the subcommand)”">​</a></h3><p>Everything else lives on a specific subcommand — <code>--config &lt;name&gt;</code>, <code>--force</code>, <code>--dry-run</code>, <code>--json</code>, <code>--yes</code>/<code>-y</code>, and any command-specific flag. These are <strong>not</strong> hoisted, so they only work after the subcommand name:</p><pre><code>noorm run build --dry-run
noorm config list --json
noorm secret rm OLD_KEY --yes
</code></pre><p>Placed before the subcommand instead, none of them are honoured — <code>noorm --dry-run run build</code> is rejected exactly like <code>noorm --bogus-flag config list</code> above, naming <code>--dry-run</code> as the offending flag. To see exactly which flags a command accepts, append <code>--help</code> to it:</p><pre><code>noorm change ff --help
noorm db create --help
noorm sql query --help
</code></pre><h2 id="the-config-c-overload" tabindex="-1">The <code>--config</code> / <code>-c</code> overload <a class="header-anchor" href="#the-config-c-overload" aria-label="Permalink to “The --config / -c overload”">​</a></h2><p><code>-c</code> is overloaded by position, which is the one sharp edge left in this system:</p><ul><li><code>noorm -c &lt;path&gt; run build</code> — global <code>--cwd</code>, because <code>-c</code> appears <strong>before</strong> the subcommand.</li><li><code>noorm run build -c &lt;name&gt;</code> — per-command <code>--config</code>, because <code>-c</code> appears <strong>after</strong> the subcommand.</li></ul><p>The first non-flag token (the subcommand name) is the boundary that decides which meaning applies. <code>--config</code> in long form has no global meaning at all — it only works after the subcommand, so <code>noorm --config prod run build</code> is not the same as <code>noorm run build --config prod</code> (the former is rejected as an unrecognized global flag).</p><h2 id="mental-model" tabindex="-1">Mental model <a class="header-anchor" href="#mental-model" aria-label="Permalink to “Mental model”">​</a></h2><p><code>noorm</code> has exactly one true global, <code>-c</code>/<code>--cwd</code>, and everything else is command-scoped. Put every flag right next to the subcommand it modifies:</p><pre><code>noorm &lt;subcommand&gt; &lt;flags…&gt; &lt;positional args…&gt;
</code></pre><p>If a flag isn&#39;t being honored, it&#39;s placed before the subcommand boundary — or it&#39;s a typo, in which case <code>noorm</code> now says so instead of silently dropping it.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to “Related”">​</a></h2><ul><li><a href="./help.html"><code>noorm</code> help conventions</a> — how to find a command&#39;s flags.</li><li><a href="./../headless.html">Headless reference</a> — full table of common flags.</li><li><a href="./../guide/troubleshooting.html">Troubleshooting</a> — quick fixes for common surprises.</li></ul>`,29)])])}const f=o(c,[["render",d]]);export{g as __pageData,f as default};
